-- 191 · 26 BÀI VIẾT B1 CHO CÂY LUYỆN TẬP (lô 37, 04/11).
--
-- Sinh bằng scripts/nhap/lo37_viet_b1.mjs, đừng sửa tay. Các dòng « Cần soạn » của B1-PE trong kế hoạch,
-- trừ hai bài thi thu nhỏ: 4 miễn phí, 22 VIP, 65 câu. Viết tự do có bài mẫu; phân tích đề, liên kết,
-- câu và thì có QCM, điền từ, xếp thứ tự. Id tiền tố b1pe.

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe01d1602d', 'practice', 'Écriture B1 : lire le sujet', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez les trois sujets, puis répondez aux questions. Vous ne devez pas écrire le texte.</p>', '<p><strong>Sujet 1.</strong> Votre ville veut fermer la piscine municipale pour construire un parking. Vous écrivez au maire pour donner votre avis et proposer une autre solution. (160 mots minimum)</p><p><strong>Sujet 2.</strong> Sur le forum d''un site pour étudiants, une personne demande s''il faut travailler pendant ses études. Vous répondez en donnant votre opinion et des exemples. (160 mots minimum)</p><p><strong>Sujet 3.</strong> Le journal de votre école prépare un numéro sur les voyages. Vous racontez un voyage qui vous a marqué et vous expliquez ce qu''il vous a appris. (160 mots minimum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un sujet (nom masculin) : đề bài\n• le destinataire (nom masculin) : người nhận\n• le but (nom masculin) : mục đích\n• municipal (adjectif) : thuộc thành phố\n• marquer (verbe) : để lại dấu ấn","explications":"• Gạch dưới ba điều trong đề: viết cho ai, để làm gì, thể loại gì.\n• Đề thường có hai động từ nhiệm vụ (raconter và expliquer, donner et proposer): làm đủ cả hai.","kyNang":"B1-PE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T08:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11000', 'b1pe01d1602d', 1, 'qcm', 'Sujet 1 : quel type de texte faut-il écrire ?', '{"options":["un message sur un forum","un article","une lettre"]}'::jsonb, '{"answer":2}'::jsonb, '« vous écrivez au maire »: viết cho một người cụ thể là thư.'), ('qmw1kkd11001', 'b1pe01d1602d', 2, 'qcm', 'Sujet 1 : quel est le but du texte ?', '{"options":["demander une information","donner son avis et proposer une solution","raconter un souvenir"]}'::jsonb, '{"answer":1}'::jsonb, '« pour donner votre avis et proposer une autre solution »: hai việc, thiếu một là mất điểm.'), ('qmw1kkd11002', 'b1pe01d1602d', 3, 'qcm', 'Sujet 2 : qui va lire votre texte ?', '{"options":["un ami proche","le directeur de l''université","les autres utilisateurs du forum"]}'::jsonb, '{"answer":2}'::jsonb, '« sur le forum d''un site pour étudiants »: người đọc là sinh viên khác, giọng thân thiện vừa phải.'), ('qmw1kkd11003', 'b1pe01d1602d', 4, 'qcm', 'Sujet 2 : que faut-il ajouter à votre opinion ?', '{"options":["des excuses","une invitation","des exemples"]}'::jsonb, '{"answer":2}'::jsonb, '« en donnant votre opinion et des exemples ».'), ('qmw1kkd11004', 'b1pe01d1602d', 5, 'qcm', 'Sujet 3 : le texte doit contenir…', '{"options":["un récit et une réflexion","seulement un récit","seulement une opinion sur les voyages"]}'::jsonb, '{"answer":0}'::jsonb, '« vous racontez un voyage » rồi « vous expliquez ce qu''il vous a appris »: kể và rút ra điều học được.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe02d1802e', 'practice', 'Écriture B1 : trois idées, un plan', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Votre entreprise propose de passer à la semaine de quatre jours. Le directeur demande l''avis des salariés. Vous lui écrivez un courriel.</p><p>Écrivez seulement le plan de ce courriel : une introduction, trois idées avec chacune un exemple, une conclusion. Des phrases courtes suffisent. (40 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un salarié (nom masculin) : nhân viên\n• un essai (nom masculin) : sự thử nghiệm\n• une permanence (nom féminin) : ca trực\n• un bilan (nom masculin) : tổng kết\n• plutôt (adverbe) : khá là, nghiêng về","explications":"• Dàn ý B1 chuẩn: mở bài, hai hoặc ba ý (mỗi ý một ví dụ), kết bài.\n• Một ý có thể là mặt hạn chế kèm giải pháp: bài sẽ cân bằng và thuyết phục hơn.","kyNang":"B1-PE-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T08:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11005', 'b1pe02d1802e', 1, 'open', 'Écrivez votre plan.', '{}'::jsonb, '{"model":"Introduction : je réponds à la demande du directeur et je dis que je suis plutôt pour.\nIdée 1 : plus de temps pour la famille. Exemple : emmener mes enfants à l''école le vendredi.\nIdée 2 : moins de fatigue, donc un meilleur travail. Exemple : moins d''erreurs le lundi matin.\nIdée 3 : un problème à régler, les clients. Exemple : organiser une permanence le vendredi.\nConclusion : proposer un essai de six mois, puis faire un bilan ensemble."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe03d1902f', 'practice', 'Écriture B1 : hors sujet ?', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le sujet et le plan de Minh, puis répondez.</p>', '<p><strong>Sujet :</strong> vous avez passé une semaine dans une famille d''accueil en France. Vous écrivez un article pour le blog de votre école : vous racontez votre séjour et vous dites si vous conseillez cette expérience aux autres élèves. (160 mots minimum)</p><p><strong>Plan de Minh :</strong> 1. Présentation de la ville de Tours et de son histoire. 2. Les repas avec la famille et la découverte du fromage. 3. Le prix des billets d''avion entre Hanoï et Paris. 4. Mon conseil : partir en famille d''accueil, parce qu''on progresse vite en français.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• hors sujet (expression) : lạc đề\n• une famille d''accueil (nom féminin) : gia đình bản xứ đón học sinh\n• un séjour (nom masculin) : kỳ lưu trú\n• conseiller (verbe) : khuyên\n• progresser (verbe) : tiến bộ","explications":"• Với mỗi ý trong dàn ý, hỏi: ý này trả lời phần nào của đề? Không trả lời được là lạc đề.\n• Phần giới thiệu bối cảnh chỉ nên một hai câu.","isPremium":true,"price":19000,"kyNang":"B1-PE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T08:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11006', 'b1pe03d1902f', 1, 'qcm', 'Quelle partie du plan est hors sujet ?', '{"options":["la partie 4","la partie 2","la partie 3"]}'::jsonb, '{"answer":2}'::jsonb, '« le prix des billets d''avion » không thuộc chuyện kể kỳ lưu trú, cũng không phải lời khuyên.'), ('qmw1kkd11007', 'b1pe03d1902f', 2, 'qcm', 'La partie 1 est-elle un bon début ?', '{"options":["Non, elle parle de la ville au lieu du séjour.","Oui, c''est l''idée la plus importante.","Oui, l''histoire de la ville est demandée."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề hỏi « vous racontez votre séjour », không hỏi lịch sử thành phố: một câu giới thiệu là đủ.'), ('qmw1kkd11008', 'b1pe03d1902f', 3, 'open', 'Réécrivez le plan pour qu''il réponde entièrement au sujet. (40 mots minimum)', '{}'::jsonb, '{"model":"1. Introduction : je suis parti une semaine à Tours, chez la famille Martin, pour améliorer mon français.\n2. Le séjour : les repas en famille, la découverte du fromage, une sortie au château d''Amboise.\n3. Les difficultés : je ne comprenais pas tout au début, mais tout le monde était patient.\n4. Mon conseil : je recommande cette expérience, parce qu''on progresse vite et qu''on découvre la vraie vie française."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe04d1902g', 'practice', 'Écriture B1 : un plan en cinq minutes', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Pour chaque sujet, écrivez un plan en cinq minutes au maximum : introduction, deux ou trois idées avec un exemple, conclusion.</p>', '<p><strong>Sujet A.</strong> Sur un forum, une personne demande si l''on peut vraiment apprendre une langue avec une application sur son téléphone. Vous donnez votre avis.</p><p><strong>Sujet B.</strong> Votre quartier organise une fête des voisins. Vous écrivez au comité d''organisation pour proposer des activités et dire comment vous pouvez aider.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une application (nom féminin) : ứng dụng\n• motivant (adjectif) : tạo động lực\n• un comité (nom masculin) : ban (tổ chức)\n• apporter (verbe) : mang đến\n• installer (verbe) : sắp đặt, dựng","explications":"• Trong phòng thi, 5 phút lập dàn ý giúp tiết kiệm 10 phút sửa bài.\n• Chỉ ghi từ khoá, không viết câu hoàn chỉnh khi lập dàn ý.","isPremium":true,"price":19000,"kyNang":"B1-PE-1","vong":"on","thuTu":4}'::jsonb, '2026-11-04T08:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11009', 'b1pe04d1902g', 1, 'open', 'Sujet A : écrivez votre plan. (40 mots minimum)', '{}'::jsonb, '{"model":"Introduction : oui, mais pas seulement avec une application.\nIdée 1 : c''est pratique et motivant. Exemple : dix minutes par jour dans le bus.\nIdée 2 : on ne parle pas assez. Exemple : je comprenais les mots, mais je ne savais pas répondre au téléphone.\nConclusion : utiliser l''application avec un cours ou un partenaire de conversation."}'::jsonb, null), ('qmw1kkd1100a', 'b1pe04d1902g', 2, 'open', 'Sujet B : écrivez votre plan. (40 mots minimum)', '{}'::jsonb, '{"model":"Introduction : je me présente, j''habite au numéro 12 depuis deux ans.\nIdée 1 : des activités pour tous. Exemple : un repas où chacun apporte un plat, des jeux pour les enfants.\nIdée 2 : mon aide. Exemple : installer les tables le matin et préparer des nems.\nConclusion : je donne mon numéro de téléphone et je propose une réunion."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe05d1902h', 'practice', 'Écriture B1 : plan pour un nouveau sujet', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Le lycée de votre ville veut interdire les téléphones portables dans tout l''établissement, même pendant les pauses. Vous écrivez une lettre au journal local pour donner votre opinion.</p><p>Écrivez le plan de cette lettre : formule d''appel, introduction, deux ou trois idées avec des exemples, conclusion, formule de politesse. (50 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• interdire (verbe) : cấm\n• l''établissement (nom masculin) : trường, cơ sở\n• exagéré (adjectif) : quá đáng\n• prévenir (verbe) : báo trước\n• un casier (nom masculin) : tủ cá nhân có khoá","explications":"• Thư gửi toà soạn cần khuôn thư: lời chào đầu, lời chào cuối, chữ ký.\n• Lập trường có sắc thái (đồng ý một phần) thường thuyết phục hơn phản đối hoàn toàn.","isPremium":true,"price":19000,"kyNang":"B1-PE-1","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T08:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100b', 'b1pe05d1902h', 1, 'open', 'Écrivez votre plan.', '{}'::jsonb, '{"model":"Formule d''appel : Madame, Monsieur,\nIntroduction : j''ai lu votre article sur l''interdiction des portables au lycée ; je suis élève et je ne suis pas d''accord.\nIdée 1 : en classe, l''interdiction est juste. Exemple : les notifications empêchent de se concentrer.\nIdée 2 : pendant les pauses, c''est exagéré. Exemple : on utilise le téléphone pour prévenir ses parents.\nIdée 3 : une meilleure solution, des règles claires et des casiers pour ranger les téléphones.\nConclusion : écouter aussi l''avis des élèves.\nFormule de politesse : Veuillez agréer, Madame, Monsieur, mes salutations distinguées."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe06d1902i', 'practice', 'Écriture B1 : un problème dans mon quartier', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Dans votre quartier, il y a un problème (bruit, propreté, sécurité, circulation…). Vous écrivez à la mairie.</p><p>Écrivez seulement le premier paragraphe : présentez la situation (où, depuis quand, ce qui se passe) et ses conséquences pour les habitants. (80 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le trottoir (nom masculin) : vỉa hè\n• s''entendre (verbe) : nghe thấy được\n• par terre (expression) : trên mặt đất\n• âgé (adjectif) : lớn tuổi\n• le verre cassé (expression) : mảnh kính vỡ","explications":"• Sự việc rõ ràng có đủ: ở đâu, từ khi nào, chuyện gì, hậu quả ra sao.\n• Dùng « depuis » + thời điểm cho việc vẫn còn tiếp diễn: depuis le mois de mars.","isPremium":true,"price":19000,"kyNang":"B1-PE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T08:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100c', 'b1pe06d1902i', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"J''habite rue des Lilas, dans le quartier de la gare, depuis cinq ans. Depuis le mois de mars, un bar a ouvert au coin de la rue et il reste ouvert jusqu''à deux heures du matin. Chaque soir, des clients discutent fort sur le trottoir, la musique s''entend jusqu''au troisième étage et des bouteilles sont laissées par terre. Plusieurs voisins âgés ne dorment presque plus, et les parents ont peur de laisser leurs enfants marcher seuls le matin, à cause du verre cassé. Nous avons déjà appelé la police deux fois, sans résultat."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe07d1902j', 'practice', 'Écriture B1 : un choix important', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Racontez un choix important que vous avez fait (études, travail, déménagement…).</p><p>Expliquez la situation avant, ce que vous avez décidé, pourquoi, et ce qui s''est passé ensuite. (100 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un comptable (nom masculin) : kế toán\n• un rythme (nom masculin) : nhịp sống\n• quitter son poste (expression) : nghỉ việc\n• le graphisme (nom masculin) : thiết kế đồ hoạ\n• regretter (verbe) : hối tiếc","explications":"• Bối cảnh trước quyết định dùng imparfait, quyết định và diễn biến dùng passé composé.\n• Thêm lý do bằng « car », « parce que » để sự việc có logic.","isPremium":true,"price":19000,"kyNang":"B1-PE-2","vong":"on","thuTu":4}'::jsonb, '2026-11-04T08:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100d', 'b1pe07d1902j', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Il y a trois ans, je travaillais comme comptable dans une grande banque à Hô Chi Minh-Ville. J''avais un bon salaire, mais je rentrais tard tous les soirs et je ne voyais presque jamais mes amis. Un jour, après une réunion de dix heures, j''ai compris que ce rythme ne me rendait pas heureuse. J''ai donc décidé de quitter mon poste pour reprendre des études de graphisme, ma passion depuis l''enfance. Mes parents étaient inquiets, car je perdais une situation stable. Les premiers mois ont été difficiles financièrement. Pourtant, aujourd''hui, je travaille dans un petit studio et je ne regrette rien. J''ai appris qu''un bon choix n''est pas toujours le plus sûr."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe08d1902k', 'practice', 'Écriture B1 : que s''est-il passé ?', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Le mois dernier, un concert organisé par votre association a été annulé au dernier moment par la mairie. Les membres écrivent au journal de la ville pour expliquer les faits et donner leur avis.</p><p>Écrivez le premier paragraphe de cette lettre : racontez précisément ce qui s''est passé. (80 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• annuler (verbe) : huỷ\n• une autorisation (nom féminin) : giấy phép\n• réserver (verbe) : đặt chỗ\n• un orage (nom masculin) : giông bão\n• prévenir (verbe) : báo trước","explications":"• Plus-que-parfait cho việc xảy ra trước một việc quá khứ khác: nous avions obtenu les autorisations.\n• Ngày giờ cụ thể làm sự việc rõ và đáng tin.","isPremium":true,"price":19000,"kyNang":"B1-PE-2","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T08:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100e', 'b1pe08d1902k', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Notre association, Musique pour tous, préparait depuis six mois un concert gratuit au parc Jean-Moulin pour le samedi 14 juin. Nous avions obtenu toutes les autorisations en avril, et plus de trois cents personnes avaient réservé leur place. Pourtant, le vendredi 13 juin à 17 heures, la mairie nous a téléphoné pour annuler l''événement, à cause d''un risque d''orage. Nous n''avons eu que quelques heures pour prévenir le public et les musiciens. Le lendemain, il a fait beau toute la journée, et aucun orage n''a éclaté."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe09d1902l', 'practice', 'Écriture B1 : les réseaux sociaux, pour ou contre ?', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Sur le forum de votre école, on pose la question : les réseaux sociaux nous rapprochent-ils ou nous éloignent-ils des autres ?</p><p>Donnez votre opinion avec deux idées. Pour chaque idée, donnez une raison et un exemple. (120 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• rapprocher (verbe) : làm gần lại\n• éloigner (verbe) : làm xa cách\n• garder le contact (expression) : giữ liên lạc\n• une passion (nom féminin) : niềm đam mê\n• au lieu de (expression) : thay vì","explications":"• Mỗi ý đủ ba phần: ý (d''abord…), lý do (car, parce que), ví dụ (par exemple…).\n• Ví dụ cá nhân (mon frère, moi) làm bài sống động hơn ví dụ chung chung.","kyNang":"B1-PE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T08:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100f', 'b1pe09d1902l', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"À mon avis, les réseaux sociaux peuvent nous rapprocher, mais seulement si on les utilise bien. D''abord, ils permettent de garder le contact avec des personnes qui vivent loin. Par exemple, mon frère étudie au Canada et nous nous parlons en vidéo chaque semaine, ce qui était impossible pour mes parents à mon âge. Ensuite, ils aident à trouver des gens qui ont les mêmes passions. Moi, j''ai rencontré un groupe de photographes amateurs grâce à Instagram, et nous sortons maintenant ensemble le week-end. Cependant, je remarque que, pendant les repas, beaucoup de mes amis regardent leur écran au lieu de discuter. Les réseaux nous rapprochent donc de ceux qui sont loin, mais parfois nous éloignent de ceux qui sont à côté."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe10d1902m', 'practice', 'Écriture B1 : que faire contre le plastique ?', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Le magazine de votre ville lance un débat : que peut-on faire, chacun à son niveau, pour utiliser moins de plastique ?</p><p>Donnez votre opinion et faites au moins deux propositions concrètes, avec une raison pour chacune. (120 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une gourde (nom féminin) : bình nước mang theo\n• un déchet (nom masculin) : rác thải\n• en vrac (expression) : bán cân, không bao bì\n• un geste (nom masculin) : hành động nhỏ\n• adopter (verbe) : áp dụng","explications":"• Đề xuất dùng conditionnel cho lịch sự: la ville pourrait aider.\n• Kết bằng một câu nhìn xa: si beaucoup d''habitants…, ils feront une vraie différence.","isPremium":true,"price":19000,"kyNang":"B1-PE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T08:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100g', 'b1pe10d1902m', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Je pense que chacun peut agir contre le plastique, sans attendre les décisions des gouvernements. Ma première proposition est simple : avoir toujours sur soi un sac en tissu et une gourde. En effet, la plupart des déchets plastiques viennent d''objets que l''on utilise une seule fois, comme les sacs et les bouteilles. Depuis que j''ai pris cette habitude, je n''achète presque plus d''eau en bouteille. Ma deuxième proposition concerne les magasins : la ville pourrait aider les épiceries qui vendent en vrac, par exemple en baissant leurs loyers. Ainsi, les clients pourraient venir avec leurs propres boîtes. Bien sûr, ces gestes ne suffiront pas à tout changer, mais s''ils sont adoptés par beaucoup d''habitants, ils feront une vraie différence. Et c''est souvent l''exemple des voisins qui donne envie de changer."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe11d1a02n', 'practice', 'Écriture B1 : étudier à l''étranger', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Un ami hésite à partir étudier un an à l''étranger. Il vous demande votre avis par courriel.</p><p>Répondez-lui : donnez votre opinion avec deux arguments, chacun expliqué par une raison et un exemple. (120 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• hésiter (verbe) : do dự\n• progresser (verbe) : tiến bộ\n• autonome (adjectif) : tự lập\n• les papiers administratifs (expression) : giấy tờ hành chính\n• manquer à quelqu''un (verbe) : khiến ai nhớ","explications":"• Lời khuyên: tu devrais + động từ nguyên mẫu.\n• Đoán trước một phản bác (ta famille va te manquer) rồi trả lời nó: bài thuyết phục hơn.","isPremium":true,"price":19000,"kyNang":"B1-PE-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T08:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100h', 'b1pe11d1a02n', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Salut Nam,\nTu me demandes si tu dois partir étudier un an à Lyon. Franchement, je pense que tu devrais y aller. D''abord, c''est le meilleur moyen de progresser en langue. Quand on vit dans un pays, on parle français du matin au soir : au supermarché, à la banque, avec ses colocataires. Ma cousine est partie à Toulouse l''année dernière et, en six mois, elle parlait sans avoir peur. Ensuite, tu deviendras plus autonome, parce que tu devras tout organiser seul, du logement aux papiers administratifs. C''est difficile au début, mais ce sera très utile pour ton futur travail. Bien sûr, ta famille va te manquer. Mais un an passe vite, et tu pourras appeler tes parents tous les jours.\nÀ bientôt,\nLinh"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe12d1a02o', 'practice', 'Écriture B1 : la ville ou la campagne', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Un magazine en ligne demande à ses lecteurs : après vos études, préférez-vous vivre en ville ou à la campagne ?</p><p>Prenez clairement position et justifiez votre choix avec des raisons et des exemples. (120 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• prendre position (expression) : nêu rõ lập trường\n• justifier (verbe) : chứng minh, lý giải\n• déménager (verbe) : chuyển nhà\n• une exposition (nom féminin) : triển lãm\n• s''installer (verbe) : định cư","explications":"• Lập trường rõ ngay câu đầu: je choisirais sans hésiter…\n• Thừa nhận mặt tốt của phía kia (je reconnais que…) không làm yếu lập trường, mà làm bài cân bằng.","isPremium":true,"price":19000,"kyNang":"B1-PE-3","vong":"on","thuTu":5}'::jsonb, '2026-11-04T08:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100i', 'b1pe12d1a02o', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Personnellement, je choisirais sans hésiter la ville, au moins pendant les premières années après mes études. La raison principale est le travail : dans une grande ville comme Hanoï, les entreprises sont nombreuses et on peut changer d''emploi sans déménager. Mon cousin, qui vit à la campagne, doit faire une heure de route chaque matin pour aller au bureau. De plus, la ville offre une vie culturelle très riche. Le week-end, je peux aller au cinéma, voir une exposition ou suivre un cours de danse, tout cela à quinze minutes de chez moi. Je reconnais que la campagne est plus calme et que l''air y est plus pur. C''est pourquoi j''aimerais peut-être m''y installer plus tard, quand j''aurai des enfants. Pour l''instant, la ville correspond mieux à mes projets."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe13d1a02p', 'practice', 'Écriture B1 : à mon avis', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Votre ville envisage de rendre les transports en commun gratuits pour tous les habitants. Vous écrivez au journal local.</p><p>Écrivez le paragraphe où vous donnez votre opinion : votre position, au moins deux arguments, des exemples. (120 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la gratuité (nom féminin) : sự miễn phí\n• les moyens (nom masculin pluriel) : tiền bạc, khả năng tài chính\n• un abonnement (nom masculin) : vé tháng\n• un embouteillage (nom masculin) : tắc đường\n• un investissement (nom masculin) : khoản đầu tư","explications":"• Mở đoạn bằng câu lập trường, đóng đoạn bằng câu khẳng định lại.\n• « Certes…, mais… » cho phép nhượng bộ rồi giữ vững ý mình.","isPremium":true,"price":19000,"kyNang":"B1-PE-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-04T08:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100j', 'b1pe13d1a02p', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"À mon avis, la gratuité des transports en commun serait une excellente décision pour notre ville. Tout d''abord, elle aiderait les familles qui ont peu de moyens. Aujourd''hui, un abonnement mensuel coûte quarante euros : pour une famille de quatre personnes, c''est une vraie dépense. Ensuite, des bus gratuits pousseraient beaucoup d''automobilistes à laisser leur voiture au garage. On le voit à Dunkerque, où le nombre de passagers a fortement augmenté depuis que le bus est gratuit. Il y aurait donc moins d''embouteillages et moins de pollution dans le centre. Certes, cette mesure aurait un coût pour la ville, mais je suis convaincu qu''une ville plus propre et plus juste vaut cet investissement. J''espère donc que le conseil municipal aura le courage de l''essayer."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe14d1a02q', 'practice', 'Écriture B1 : passer d''une idée à l''autre', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez l''article avec les mots de liaison : d''abord, de plus, cependant, en conclusion. Chaque mot sert une fois. Puis faites les deux exercices suivants.</p>', '<p><strong>Faut-il apprendre à coder à l''école ?</strong></p><p>(1) ______, apprendre à coder développe la logique : un élève qui écrit un petit programme doit organiser ses idées étape par étape.</p><p>(2) ______, le numérique est présent dans presque tous les métiers, et savoir coder sera un atout pour trouver un emploi.</p><p>(3) ______, les heures de cours ne sont pas illimitées : ajouter le code obligerait à réduire d''autres matières, comme le sport ou la musique.</p><p>(4) ______, je pense que le code a sa place à l''école, mais sous la forme d''un atelier facultatif.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un mot de liaison (nom masculin) : từ nối\n• un atout (nom masculin) : lợi thế\n• illimité (adjectif) : không giới hạn\n• facultatif (adjectif) : tự chọn\n• le télétravail (nom masculin) : làm việc từ xa","explications":"• Câu chuyển đoạn tốt nhắc lại ý vừa xong rồi mở ý mới.\n• Một câu hỏi (Mais qu''en est-il… ?) là cách chuyển đoạn tự nhiên.","kyNang":"B1-PE-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T08:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100k', 'b1pe14d1a02q', 1, 'fill', 'Mot de liaison (1) :', '{}'::jsonb, '{"accepted":"d''abord|d’abord|tout d''abord|tout d’abord"}'::jsonb, 'Ý thứ nhất trong chuỗi lập luận: d''abord.'), ('qmw1kkd1100l', 'b1pe14d1a02q', 2, 'fill', 'Mot de liaison (2) :', '{}'::jsonb, '{"accepted":"de plus"}'::jsonb, 'Thêm một lợi ích cùng hướng: de plus.'), ('qmw1kkd1100m', 'b1pe14d1a02q', 3, 'fill', 'Mot de liaison (3) :', '{}'::jsonb, '{"accepted":"cependant"}'::jsonb, 'Đổi hướng sang mặt hạn chế: cependant.'), ('qmw1kkd1100n', 'b1pe14d1a02q', 4, 'fill', 'Mot de liaison (4) :', '{}'::jsonb, '{"accepted":"en conclusion"}'::jsonb, 'Đoạn cuối tóm ý và nêu lập trường: en conclusion.'), ('qmw1kkd1100o', 'b1pe14d1a02q', 5, 'ordre', 'Remettez dans l''ordre ce passage d''un paragraphe à l''autre.', '{"elements":[{"id":"emw1kkd1100q","texte":"Mais qu''en est-il pour les entreprises ?"},{"id":"emw1kkd1100s","texte":"En effet, il est plus difficile de garder une équipe unie à distance."},{"id":"emw1kkd1100r","texte":"Pour elles, la situation est plus compliquée."},{"id":"emw1kkd1100p","texte":"Nous avons vu les avantages du télétravail pour les salariés."}]}'::jsonb, '{"elements":[{"id":"emw1kkd1100p","texte":"Nous avons vu les avantages du télétravail pour les salariés."},{"id":"emw1kkd1100q","texte":"Mais qu''en est-il pour les entreprises ?"},{"id":"emw1kkd1100r","texte":"Pour elles, la situation est plus compliquée."},{"id":"emw1kkd1100s","texte":"En effet, il est plus difficile de garder une équipe unie à distance."}]}'::jsonb, 'Câu tổng kết đoạn trước, câu hỏi mở đoạn mới, câu chủ đề, rồi câu giải thích bằng « en effet ».'), ('qmw1kkd1100t', 'b1pe14d1a02q', 6, 'open', 'Écrivez une phrase de transition entre deux paragraphes : le premier présente les avantages des vacances à l''étranger, le second leurs inconvénients. (15 mots minimum)', '{}'::jsonb, '{"model":"Pourtant, partir à l''étranger n''a pas que des avantages, et certains aspects méritent d''être pris en compte avant de réserver."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe15d1a02r', 'practice', 'Écriture B1 : mettez les paragraphes en ordre', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Chaque exercice présente les parties d''un texte dans le désordre. Remettez-les dans l''ordre.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une réclamation (nom féminin) : khiếu nại\n• un colis (nom masculin) : bưu kiện\n• éclater (verbe) : nổ ra, bùng lên\n• s''abriter (verbe) : trú (mưa)\n• trempé (adjectif) : ướt sũng","explications":"• Tìm câu mở (chào hỏi, bối cảnh) và câu kết (finalement, donc, lời chào) trước.\n• Từ nối ở đầu câu (pourtant, par exemple, au bout de) cho biết câu đó không thể đứng đầu.","isPremium":true,"price":19000,"kyNang":"B1-PE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T08:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1100u', 'b1pe15d1a02r', 1, 'ordre', 'Un courriel de réclamation', '{"elements":[{"id":"emw1kkd1100v","texte":"Madame, Monsieur, j''ai commandé une machine à café sur votre site le 2 mars (commande n° 4581)."},{"id":"emw1kkd1100w","texte":"Le colis est arrivé le 10 mars, mais la machine ne s''allume pas."},{"id":"emw1kkd1100y","texte":"Dans l''attente de votre réponse, je vous prie d''agréer mes salutations distinguées."},{"id":"emw1kkd1100x","texte":"Je vous demande donc de l''échanger ou de me rembourser dans les plus brefs délais."}]}'::jsonb, '{"elements":[{"id":"emw1kkd1100v","texte":"Madame, Monsieur, j''ai commandé une machine à café sur votre site le 2 mars (commande n° 4581)."},{"id":"emw1kkd1100w","texte":"Le colis est arrivé le 10 mars, mais la machine ne s''allume pas."},{"id":"emw1kkd1100x","texte":"Je vous demande donc de l''échanger ou de me rembourser dans les plus brefs délais."},{"id":"emw1kkd1100y","texte":"Dans l''attente de votre réponse, je vous prie d''agréer mes salutations distinguées."}]}'::jsonb, 'Thư khiếu nại: chào và nêu đơn hàng, sự việc, yêu cầu, lời chào cuối.'), ('qmw1kkd1100z', 'b1pe15d1a02r', 2, 'ordre', 'Un article d''opinion', '{"elements":[{"id":"emw1kkd11011","texte":"Pour beaucoup d''élèves, c''est une bonne idée : ces repas sont meilleurs pour la planète."},{"id":"emw1kkd11012","texte":"Pourtant, certains parents craignent que leurs enfants ne mangent pas assez de protéines."},{"id":"emw1kkd11010","texte":"Depuis la rentrée, la cantine du collège propose un repas végétarien par semaine."},{"id":"emw1kkd11013","texte":"Selon moi, un repas par semaine est un bon équilibre, à condition qu''il soit varié."}]}'::jsonb, '{"elements":[{"id":"emw1kkd11010","texte":"Depuis la rentrée, la cantine du collège propose un repas végétarien par semaine."},{"id":"emw1kkd11011","texte":"Pour beaucoup d''élèves, c''est une bonne idée : ces repas sont meilleurs pour la planète."},{"id":"emw1kkd11012","texte":"Pourtant, certains parents craignent que leurs enfants ne mangent pas assez de protéines."},{"id":"emw1kkd11013","texte":"Selon moi, un repas par semaine est un bon équilibre, à condition qu''il soit varié."}]}'::jsonb, 'Bài nghị luận: tình huống, ý ủng hộ, ý phản đối (pourtant), ý kiến người viết.'), ('qmw1kkd11014', 'b1pe15d1a02r', 3, 'ordre', 'Un récit', '{"elements":[{"id":"emw1kkd11017","texte":"Nous nous sommes abrités dans une cabane en attendant la fin de la pluie."},{"id":"emw1kkd11015","texte":"Samedi dernier, je suis parti faire une randonnée en montagne avec deux amis."},{"id":"emw1kkd11016","texte":"Au bout de deux heures, le ciel est devenu noir et un orage a éclaté."},{"id":"emw1kkd11018","texte":"Finalement, nous sommes rentrés trempés, mais avec un très bon souvenir."}]}'::jsonb, '{"elements":[{"id":"emw1kkd11015","texte":"Samedi dernier, je suis parti faire une randonnée en montagne avec deux amis."},{"id":"emw1kkd11016","texte":"Au bout de deux heures, le ciel est devenu noir et un orage a éclaté."},{"id":"emw1kkd11017","texte":"Nous nous sommes abrités dans une cabane en attendant la fin de la pluie."},{"id":"emw1kkd11018","texte":"Finalement, nous sommes rentrés trempés, mais avec un très bon souvenir."}]}'::jsonb, 'Câu chuyện: bối cảnh, biến cố (au bout de…), cách xử lý, kết (finalement).'), ('qmw1kkd11019', 'b1pe15d1a02r', 4, 'ordre', 'Un message sur un forum', '{"elements":[{"id":"emw1kkd1101d","texte":"Je te conseille donc d''essayer, Julie, mais choisis bien tes colocataires !"},{"id":"emw1kkd1101b","texte":"Moi, je vis en colocation depuis deux ans et c''est une expérience très positive."},{"id":"emw1kkd1101c","texte":"Par exemple, nous partageons les courses, ce qui nous fait économiser beaucoup d''argent."},{"id":"emw1kkd1101a","texte":"Bonjour à tous, je réponds à la question de Julie sur les colocations."}]}'::jsonb, '{"elements":[{"id":"emw1kkd1101a","texte":"Bonjour à tous, je réponds à la question de Julie sur les colocations."},{"id":"emw1kkd1101b","texte":"Moi, je vis en colocation depuis deux ans et c''est une expérience très positive."},{"id":"emw1kkd1101c","texte":"Par exemple, nous partageons les courses, ce qui nous fait économiser beaucoup d''argent."},{"id":"emw1kkd1101d","texte":"Je te conseille donc d''essayer, Julie, mais choisis bien tes colocataires !"}]}'::jsonb, 'Bài diễn đàn: chào và nhắc câu hỏi, ý kiến, ví dụ, lời khuyên kết.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe16d1a02s', 'practice', 'Écriture B1 : introduction et conclusion', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le développement d''un article sur le bénévolat, puis écrivez son introduction et sa conclusion.</p>', '<p>D''abord, le bénévolat permet d''aider les autres. Dans notre ville, les bénévoles de l''association Repas solidaires servent chaque soir plus de cent repas aux personnes sans domicile.</p><p>Ensuite, il est utile pour les bénévoles eux-mêmes. Ils apprennent à travailler en équipe, à organiser un événement ou à parler en public, des compétences qui intéressent aussi les employeurs.</p><p>Cependant, tout le monde n''a pas le temps de s''engager. Beaucoup de jeunes travaillent déjà pour payer leurs études et ne peuvent pas donner plusieurs soirées par semaine.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le bénévolat (nom masculin) : hoạt động tình nguyện\n• un bénévole (nom masculin) : tình nguyện viên\n• solidaire (adjectif) : tương trợ\n• s''engager (verbe) : tham gia, cam kết\n• une compétence (nom féminin) : kỹ năng","explications":"• Mở bài: một câu dẫn (con số, câu hỏi), một câu nêu vấn đề, một câu báo dàn ý.\n• Kết bài: tóm ý bằng « en conclusion » rồi nêu ý kiến, không đưa ý mới.","isPremium":true,"price":19000,"kyNang":"B1-PE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-04T08:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1101e', 'b1pe16d1a02s', 1, 'open', 'Écrivez l''introduction : présentez le sujet et annoncez le plan. (40 mots minimum)', '{}'::jsonb, '{"model":"En France, une personne sur quatre donne un peu de son temps à une association. Mais pourquoi devenir bénévole, et est-ce vraiment possible pour tout le monde ? Nous verrons d''abord ce que le bénévolat apporte aux autres et aux bénévoles, puis ses limites."}'::jsonb, null), ('qmw1kkd1101f', 'b1pe16d1a02s', 2, 'open', 'Écrivez la conclusion : résumez les idées et donnez votre avis. (40 mots minimum)', '{}'::jsonb, '{"model":"En conclusion, le bénévolat est utile à la fois pour ceux qui reçoivent de l''aide et pour ceux qui la donnent. Même si tout le monde ne peut pas s''engager chaque semaine, je pense qu''une heure par mois suffit déjà pour changer les choses."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe17d1a02t', 'practice', 'Écriture B1 : rendez le texte fluide', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Ce texte est correct mais les phrases ne sont pas reliées. Réécrivez-le en ajoutant des mots de liaison (d''abord, ensuite, de plus, car, pourtant, donc, enfin…) et en faisant des paragraphes. (120 mots minimum)</p>', '<p>J''ai déménagé à Bordeaux en septembre. Je voulais changer de vie. J''ai trouvé un appartement près du centre. Il était petit. Il était lumineux. Je ne connaissais personne. Je me suis inscrite dans un club de théâtre. J''ai rencontré des gens sympathiques. J''ai trouvé un travail dans une librairie. Le salaire n''est pas très élevé. J''aime beaucoup ce métier. Je suis contente de mon choix. Je conseille aux personnes qui hésitent de tenter l''aventure.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• lumineux (adjectif) : sáng sủa\n• s''inscrire (verbe) : đăng ký\n• élevé (adjectif) : cao\n• tenter l''aventure (expression) : thử liều một phen\n• hésiter (verbe) : do dự","explications":"• Hai câu đối lập nối bằng mais hoặc pourtant; câu nguyên nhân nối bằng car hoặc parce que.\n• Chia bài thành đoạn theo thời gian hoặc theo ý, mỗi đoạn mở bằng một từ nối.","isPremium":true,"price":19000,"kyNang":"B1-PE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T08:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1101g', 'b1pe17d1a02t', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"En septembre, j''ai déménagé à Bordeaux, car je voulais changer de vie.\nD''abord, j''ai trouvé un appartement près du centre. Il était petit, mais très lumineux. Au début, je ne connaissais personne dans la ville. C''est pourquoi je me suis inscrite dans un club de théâtre, où j''ai rencontré des gens très sympathiques.\nEnsuite, j''ai trouvé un travail dans une librairie. Le salaire n''est pas très élevé ; pourtant, j''aime beaucoup ce métier, parce que je peux parler de livres toute la journée.\nEnfin, après quelques mois, je peux dire que je suis contente de mon choix. Je conseille donc aux personnes qui hésitent de tenter l''aventure, même si les premières semaines sont parfois difficiles. Avec un peu de patience, on finit toujours par trouver sa place."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe18d1b02u', 'practice', 'Écriture B1 : qui, que, où, dont', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Complétez chaque phrase avec qui, que (qu''), où ou dont.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• qui : chủ ngữ của động từ sau\n• que : bổ ngữ trực tiếp\n• où : nơi chốn, thời điểm\n• dont : thay cho de + danh từ\n• grandir (verbe) : lớn lên","explications":"• Ngay sau chỗ trống là động từ: thường là qui. Là một chủ ngữ (je, nous, elle): que hoặc où.\n• Động từ đi với de (parler de, avoir besoin de) hoặc quan hệ sở hữu: dont.","isPremium":true,"price":19000,"kyNang":"B1-PE-5","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T08:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1101h', 'b1pe18d1b02u', 1, 'fill', 'J''ai un ami ______ habite à Marseille.', '{}'::jsonb, '{"accepted":"qui"}'::jsonb, 'Ami là chủ ngữ của habite: qui.'), ('qmw1kkd1101i', 'b1pe18d1b02u', 2, 'fill', 'C''est le livre ______ je t''ai parlé.', '{}'::jsonb, '{"accepted":"dont"}'::jsonb, 'parler DE quelque chose: dont.'), ('qmw1kkd1101j', 'b1pe18d1b02u', 3, 'fill', 'La ville ______ j''ai grandi est au bord de la mer.', '{}'::jsonb, '{"accepted":"où"}'::jsonb, 'Nơi chốn: où.'), ('qmw1kkd1101k', 'b1pe18d1b02u', 4, 'fill', 'Le film ______ nous avons vu hier était très long.', '{}'::jsonb, '{"accepted":"que|qu''|qu’"}'::jsonb, 'Film là bổ ngữ trực tiếp của avons vu: que.'), ('qmw1kkd1101l', 'b1pe18d1b02u', 5, 'fill', 'Voici la collègue ______ le fils joue au foot avec le mien.', '{}'::jsonb, '{"accepted":"dont"}'::jsonb, 'le fils DE la collègue: dont.'), ('qmw1kkd1101m', 'b1pe18d1b02u', 6, 'fill', 'C''est un restaurant ______ propose des plats végétariens.', '{}'::jsonb, '{"accepted":"qui"}'::jsonb, 'Restaurant là chủ ngữ của propose: qui.'), ('qmw1kkd1101n', 'b1pe18d1b02u', 7, 'fill', 'Je me souviens du jour ______ nous sommes arrivés en France.', '{}'::jsonb, '{"accepted":"où"}'::jsonb, 'Thời điểm (le jour, l''année) cũng dùng où.'), ('qmw1kkd1101o', 'b1pe18d1b02u', 8, 'fill', 'La robe ______ elle a achetée est rouge.', '{}'::jsonb, '{"accepted":"qu''|qu’|que"}'::jsonb, 'Trước elle bắt đầu bằng nguyên âm, que thành qu''.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe19d1b02v', 'practice', 'Écriture B1 : une phrase plus riche', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Pour chaque exercice, choisissez la phrase correcte qui relie les deux phrases. Puis réécrivez deux groupes de phrases.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• comme : vì (đầu câu)\n• bien que : mặc dù (+ subjonctif)\n• pour + infinitif : để\n• après avoir + participe : sau khi đã\n• si bien que : đến nỗi, cho nên","explications":"• Bài B1 được điểm cấu trúc khi có câu phức: mệnh đề quan hệ, nguyên nhân, đối lập, mục đích.\n• Đừng nối mọi câu bằng et: thay một vài chỗ bằng comme, bien que, pour.","isPremium":true,"price":19000,"kyNang":"B1-PE-5","vong":"hoc","thuTu":5}'::jsonb, '2026-11-04T08:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1101p', 'b1pe19d1b02v', 1, 'qcm', 'Reliez : « J''ai rencontré une femme. Cette femme parle cinq langues. »', '{"options":["J''ai rencontré une femme dont parle cinq langues.","J''ai rencontré une femme qui parle cinq langues.","J''ai rencontré une femme que parle cinq langues."]}'::jsonb, '{"answer":1}'::jsonb, 'Femme là chủ ngữ của parle, nên dùng qui.'), ('qmw1kkd1101q', 'b1pe19d1b02v', 2, 'qcm', 'Exprimez la cause : « Il pleuvait. Nous sommes restés à la maison. »', '{"options":["Pour qu''il pleuvait, nous sommes restés à la maison.","Comme il pleuvait, nous sommes restés à la maison.","Bien qu''il pleuvait, nous sommes restés à la maison."]}'::jsonb, '{"answer":1}'::jsonb, 'comme + nguyên nhân, đặt đầu câu.'), ('qmw1kkd1101r', 'b1pe19d1b02v', 3, 'qcm', 'Exprimez l''opposition : « Elle est fatiguée. Elle continue à travailler. »', '{"options":["Parce qu''elle est fatiguée, elle continue à travailler.","Bien qu''elle est fatiguée, elle continue à travailler.","Bien qu''elle soit fatiguée, elle continue à travailler."]}'::jsonb, '{"answer":2}'::jsonb, 'bien que + subjonctif: soit, không phải est.'), ('qmw1kkd1101s', 'b1pe19d1b02v', 4, 'qcm', 'Reliez : « J''ai fini mes devoirs. Ensuite, je suis sorti. »', '{"options":["Après avoir fini mes devoirs, je suis sorti.","Avant d''avoir fini mes devoirs, je suis sorti.","Après finir mes devoirs, je suis sorti."]}'::jsonb, '{"answer":0}'::jsonb, 'après + infinitif passé: après avoir fini.'), ('qmw1kkd1101t', 'b1pe19d1b02v', 5, 'qcm', 'Exprimez le but : « Je travaille le soir. Je veux payer mes études. »', '{"options":["Je travaille le soir donc payer mes études.","Je travaille le soir parce que payer mes études.","Je travaille le soir pour payer mes études."]}'::jsonb, '{"answer":2}'::jsonb, 'Mục đích, cùng chủ ngữ: pour + infinitif.'), ('qmw1kkd1101u', 'b1pe19d1b02v', 6, 'qcm', 'Reliez : « Le quartier est calme. Je vis dans ce quartier. »', '{"options":["Le quartier dont je vis est calme.","Le quartier que je vis est calme.","Le quartier où je vis est calme."]}'::jsonb, '{"answer":2}'::jsonb, 'vivre DANS un lieu: où.'), ('qmw1kkd1101v', 'b1pe19d1b02v', 7, 'open', 'Réécrivez en une seule phrase : « Lyon est une ville. J''ai étudié dans cette ville. Cette ville est connue pour sa cuisine. » (10 mots minimum)', '{}'::jsonb, '{"model":"Lyon, où j''ai étudié, est une ville connue pour sa cuisine."}'::jsonb, null), ('qmw1kkd1101w', 'b1pe19d1b02v', 8, 'open', 'Réécrivez en une seule phrase avec une cause et une conséquence : « Le bus était en retard. Je suis arrivé après le début du cours. Le professeur n''était pas content. » (12 mots minimum)', '{}'::jsonb, '{"model":"Comme le bus était en retard, je suis arrivé après le début du cours, si bien que le professeur n''était pas content."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe20d1b02w', 'practice', 'Écriture B1 : quel temps choisir ?', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Lisez le texte et conjuguez chaque verbe au temps qui convient (imparfait, passé composé, plus-que-parfait, présent ou futur).</p>', '<p>L''année dernière, quand j''(1) ______ (habiter) à Nantes, je (2) ______ (prendre) le tram tous les matins. Un lundi de décembre, le tram (3) ______ (s''arrêter) entre deux stations. Il (4) ______ (faire) très froid et personne ne savait pourquoi. Après vingt minutes, le conducteur nous (5) ______ (expliquer) qu''un camion (6) ______ (bloquer) les rails un peu plus loin. Finalement, je (7) ______ (arriver) au bureau avec une heure de retard. Ma cheffe, qui (8) ______ (préparer) une réunion importante, n''était pas contente. Depuis ce jour, je (9) ______ (partir) toujours plus tôt, et l''année prochaine, je (10) ______ (acheter) un vélo.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une station (nom féminin) : ga, trạm (tram, métro)\n• un conducteur (nom masculin) : người lái\n• les rails (nom masculin pluriel) : đường ray\n• une cheffe (nom féminin) : sếp nữ\n• depuis ce jour (expression) : từ hôm ấy","explications":"• Imparfait: bối cảnh, thói quen, việc đang diễn ra. Passé composé: sự việc trong chuỗi kể.\n• Plus-que-parfait: việc đã xảy ra trước một việc quá khứ khác.","isPremium":true,"price":19000,"kyNang":"B1-PE-5","vong":"on","thuTu":6}'::jsonb, '2026-11-04T08:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1101x', 'b1pe20d1b02w', 1, 'fill', '(1) habiter :', '{}'::jsonb, '{"accepted":"habitais"}'::jsonb, 'Bối cảnh kéo dài trong quá khứ: imparfait.'), ('qmw1kkd1101y', 'b1pe20d1b02w', 2, 'fill', '(2) prendre :', '{}'::jsonb, '{"accepted":"prenais"}'::jsonb, 'Thói quen lặp lại (tous les matins): imparfait.'), ('qmw1kkd1101z', 'b1pe20d1b02w', 3, 'fill', '(3) s''arrêter :', '{}'::jsonb, '{"accepted":"s''est arrêté|s’est arrêté"}'::jsonb, 'Sự việc xảy ra một lần (un lundi): passé composé, động từ đại từ đi với être.'), ('qmw1kkd11020', 'b1pe20d1b02w', 4, 'fill', '(4) faire :', '{}'::jsonb, '{"accepted":"faisait"}'::jsonb, 'Thời tiết là khung cảnh: imparfait.'), ('qmw1kkd11021', 'b1pe20d1b02w', 5, 'fill', '(5) expliquer :', '{}'::jsonb, '{"accepted":"a expliqué"}'::jsonb, 'Hành động một lần trong chuỗi sự việc: passé composé.'), ('qmw1kkd11022', 'b1pe20d1b02w', 6, 'fill', '(6) bloquer :', '{}'::jsonb, '{"accepted":"avait bloqué"}'::jsonb, 'Xe tải chắn đường TRƯỚC lời giải thích: plus-que-parfait.'), ('qmw1kkd11023', 'b1pe20d1b02w', 7, 'fill', '(7) arriver :', '{}'::jsonb, '{"accepted":"suis arrivé|suis arrivée"}'::jsonb, 'Kết quả của chuỗi sự việc: passé composé với être.'), ('qmw1kkd11024', 'b1pe20d1b02w', 8, 'fill', '(8) préparer :', '{}'::jsonb, '{"accepted":"préparait|avait préparé"}'::jsonb, 'Việc đang diễn ra lúc người viết đến: imparfait (hoặc plus-que-parfait nếu đã chuẩn bị xong).'), ('qmw1kkd11025', 'b1pe20d1b02w', 9, 'fill', '(9) partir :', '{}'::jsonb, '{"accepted":"pars"}'::jsonb, 'Depuis + thói quen vẫn còn ở hiện tại: présent.'), ('qmw1kkd11026', 'b1pe20d1b02w', 10, 'fill', '(10) acheter :', '{}'::jsonb, '{"accepted":"achèterai|vais acheter"}'::jsonb, 'L''année prochaine: futur simple (hoặc futur proche).')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe21d1b02x', 'practice', 'Écriture B1 : améliorez ce texte', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Ce paragraphe d''un élève est compréhensible mais très simple. Réécrivez-le pour atteindre le niveau B1 : phrases complexes (qui, que, où, parce que, bien que…), temps variés, vocabulaire plus précis. (120 mots minimum)</p>', '<p>Je suis allé au festival de musique. Le festival était à Nîmes. Il y avait beaucoup de monde. Il faisait chaud. J''ai vu un groupe. Le groupe joue du jazz. C''était bien. Je n''avais pas de billet pour le dernier concert. J''ai attendu devant l''entrée. Un homme m''a donné un billet. Je vais revenir l''année prochaine. C''est un bon festival.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• les arènes (nom féminin pluriel) : đấu trường cổ\n• avoir du mal à (expression) : gặp khó khi\n• ému (adjectif) : xúc động\n• complet (adjectif) : hết chỗ\n• au cas où (expression) : phòng khi","explications":"• Thay « c''était bien » bằng cảm nhận cụ thể: m''a vraiment ému, à la fois douce et énergique.\n• Gộp hai câu ngắn có cùng danh từ bằng qui, que, dont, où.","isPremium":true,"price":19000,"kyNang":"B1-PE-5","vong":"chot","thuTu":7}'::jsonb, '2026-11-04T08:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11027', 'b1pe21d1b02x', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Le mois dernier, je suis allé au festival de musique de Nîmes, qui a lieu chaque été dans les arènes romaines. Comme il faisait très chaud, le public s''installait à l''ombre en attendant les premiers concerts, et il y avait tellement de monde qu''on avait du mal à circuler.\nLe deuxième soir, j''ai découvert un groupe de jazz dont je n''avais jamais entendu parler. Leur musique, à la fois douce et énergique, m''a vraiment ému.\nMalheureusement, je n''avais pas pu acheter de billet pour le dernier concert, car tout était complet depuis des semaines. J''ai donc attendu devant l''entrée, au cas où. Au bout d''une heure, un homme dont l''ami était malade m''a offert sa place. Bien que ce festival soit un peu cher, j''y reviendrai sans hésiter l''année prochaine."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe22d1b02y', 'practice', 'Écriture B1 : un courriel au directeur', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Vous travaillez dans une entreprise de 200 salariés. La direction annonce que la cantine va fermer pour réduire les dépenses. Les salariés recevront un ticket de 5 euros par jour.</p><p>Vous écrivez un courriel au directeur : vous donnez votre opinion sur cette décision et vous proposez une autre solution. (160 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la direction (nom féminin) : ban giám đốc\n• réduire les dépenses (expression) : cắt giảm chi phí\n• se dégrader (verbe) : xấu đi\n• confier (verbe) : giao phó\n• rester à disposition (expression) : sẵn sàng (trao đổi)","explications":"• Email trang trọng: có Objet, lời chào (Monsieur le Directeur), lời chào cuối, chữ ký.\n• Đề đòi hai việc: ý kiến VÀ giải pháp. Dành một đoạn riêng cho giải pháp.","isPremium":true,"price":19000,"kyNang":"B1-PE-6","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T08:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11028', 'b1pe22d1b02y', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Objet : fermeture de la cantine\n\nMonsieur le Directeur,\n\nJ''ai appris par la note du 3 novembre que la cantine allait fermer à la fin de l''année. Je comprends que l''entreprise doive réduire ses dépenses ; cependant, je pense que cette décision aura des conséquences négatives pour les salariés.\n\nD''abord, un ticket de 5 euros ne suffit pas pour déjeuner dans le quartier, où un menu coûte au moins 12 euros. Beaucoup de collègues devront donc apporter leur repas, alors que nous n''avons ni réfrigérateur ni salle pour manger. Ensuite, la cantine est le seul endroit où les équipes des différents services se rencontrent. Sans elle, l''ambiance de travail risque de se dégrader.\n\nJe voudrais donc proposer une autre solution : garder la cantine ouverte, mais confier sa gestion à une association locale qui travaille avec des produits de la région. Plusieurs entreprises voisines l''ont déjà fait et ont réduit leurs coûts d''environ 30 %.\n\nJe reste à votre disposition pour en discuter.\n\nVeuillez agréer, Monsieur le Directeur, mes salutations distinguées.\n\nThu Hà Nguyen, service comptabilité"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe23d1b02z', 'practice', 'Écriture B1 : sur le forum du lycée', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Sur le forum de votre lycée, un élève demande : « Faut-il porter un uniforme à l''école ? »</p><p>Vous répondez sur le forum : vous donnez votre opinion, avec des arguments et des exemples tirés de votre expérience. (160 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un uniforme (nom masculin) : đồng phục\n• une marque (nom féminin) : thương hiệu\n• se moquer de (verbe) : chế giễu\n• les habits (nom masculin pluriel) : quần áo\n• un compromis (nom masculin) : thoả hiệp","explications":"• Bài diễn đàn: chào người hỏi và cả nhóm, giọng thân thiện, kết bằng một câu hỏi mời trao đổi.\n• Kinh nghiệm cá nhân là ví dụ mạnh nhất: j''ai porté un uniforme pendant quatre ans.","isPremium":true,"price":19000,"kyNang":"B1-PE-6","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T08:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd11029', 'b1pe23d1b02z', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Salut Hugo, et salut à tous !\n\nTa question m''intéresse beaucoup, parce que j''ai porté un uniforme pendant quatre ans au Vietnam, avant d''arriver en France. Personnellement, je suis plutôt pour, même si ce n''est pas parfait.\n\nPremièrement, l''uniforme évite les comparaisons entre élèves. Dans mon ancien collège, personne ne savait qui avait des vêtements de marque et qui n''en avait pas. Ici, au contraire, j''ai vu des camarades se moquer d''une fille à cause de ses baskets. Deuxièmement, c''est pratique : le matin, on ne perd pas de temps à choisir ses habits, et les parents dépensent moins d''argent.\n\nJe comprends quand même ceux qui sont contre, et leurs arguments sont sérieux. À notre âge, on a envie de montrer sa personnalité, et les vêtements sont un moyen de le faire. On pourrait peut-être trouver un compromis : un uniforme simple, mais avec la liberté de choisir ses chaussures et ses accessoires.\n\nEt vous, qu''est-ce que vous en pensez ? J''ai hâte de lire vos réponses.\n\nMai Anh, terminale B"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe24d1b030', 'practice', 'Écriture B1 : pour le journal de l''école', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Votre école a organisé une « journée sans écran » : pas de téléphone, pas d''ordinateur, des activités à la place.</p><p>Vous écrivez un article pour le journal de l''école : vous racontez cette journée et vous donnez votre avis sur l''intérêt de l''expérience. (160 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un pari (nom masculin) : canh bạc, thử thách\n• autrefois (adverbe) : ngày xưa\n• un tournoi d''échecs (nom masculin) : giải cờ vua\n• dépendre de (verbe) : phụ thuộc vào\n• renouveler (verbe) : lặp lại","explications":"• Bài báo có tiêu đề, phần kể (ai, khi nào, ở đâu, chuyện gì), phần nhận xét, và tên người viết.\n• Tiêu đề dạng câu hỏi (pari réussi ?) gây tò mò cho người đọc.","isPremium":true,"price":19000,"kyNang":"B1-PE-6","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T08:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1102a', 'b1pe24d1b030', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Une journée sans écran : pari réussi ?\n\nJeudi dernier, notre école a vécu une expérience originale : pendant toute une journée, les téléphones et les ordinateurs étaient interdits. À 8 heures, chaque élève a déposé son portable dans une boîte, et les cours ont commencé avec des cahiers et des livres, comme autrefois.\n\nL''après-midi, les professeurs avaient préparé des ateliers : jeux de société, cuisine, théâtre et même un tournoi d''échecs dans la cour. Au début, beaucoup d''entre nous se sentaient perdus. Certains vérifiaient leur poche toutes les cinq minutes ! Mais peu à peu, l''ambiance a changé. On entendait des rires dans les couloirs, et des élèves qui ne se parlaient jamais ont joué ensemble.\n\nÀ mon avis, cette journée a été très utile, car elle nous a montré à quel point nous dépendons de nos écrans. Bien sûr, une seule journée ne change pas nos habitudes. C''est pourquoi je propose de renouveler l''expérience une fois par mois.\n\nPar Thanh Tùng, classe de première"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe25d1c031', 'practice', 'Écriture B1 : lettre au journal', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Dans le journal de votre ville, un article affirme que « les jeunes ne lisent plus ».</p><p>Vous écrivez au journal pour réagir : vous dites si vous êtes d''accord, en donnant des arguments et des exemples précis. (160 mots minimum)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une édition (nom féminin) : số báo\n• une affirmation (nom féminin) : khẳng định\n• une médiathèque (nom féminin) : thư viện đa phương tiện\n• emprunter (verbe) : mượn\n• un point de vue (nom masculin) : quan điểm","explications":"• Thư gửi toà soạn: nhắc bài báo (ngày, tiêu đề) ngay đoạn đầu.\n• « Je reconnais néanmoins que… » cho thấy bạn công bằng, giám khảo đánh giá cao.","isPremium":true,"price":19000,"kyNang":"B1-PE-6","vong":"on","thuTu":5}'::jsonb, '2026-11-04T08:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1102b', 'b1pe25d1c031', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"Madame, Monsieur,\n\nDans votre édition du 15 octobre, j''ai lu l''article intitulé « Les jeunes ne lisent plus ». En tant qu''étudiante de vingt ans, je ne suis pas du tout d''accord avec cette affirmation.\n\nTout d''abord, les jeunes lisent, mais pas toujours les mêmes livres que leurs parents. Dans la médiathèque de notre quartier, les mangas et les romans fantastiques sont les livres les plus empruntés, et la plupart des lecteurs ont moins de vingt-cinq ans. De plus, nous lisons énormément sur nos téléphones : des articles, des blogs, des forums. Ce n''est pas de la littérature classique, mais c''est quand même de la lecture.\n\nJe reconnais néanmoins que les longs romans attirent moins notre génération. Selon moi, l''école pourrait aider à changer cela, par exemple en laissant les élèves choisir une partie des livres étudiés en classe.\n\nJ''espère que vous publierez ce point de vue, qui me semble important. Il serait dommage de juger toute une génération sur des chiffres incomplets.\n\nVeuillez agréer, Madame, Monsieur, l''expression de mes salutations distinguées.\n\nNgọc Lan Trần"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1pe26d1c032', 'practice', 'Écriture B1 : essai de 160 mots', 'B1', array['Production écrite']::text[], 'practice', null, null, '<p>Dans votre pays, de plus en plus de jeunes choisissent de vivre en colocation après leurs études. Un magazine en ligne vous demande votre témoignage.</p><p>Vous écrivez un article : vous racontez votre expérience ou celle d''une personne que vous connaissez, et vous donnez votre opinion sur ce mode de vie. (160 mots minimum, 45 minutes)</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un témoignage (nom masculin) : lời kể, chứng từ\n• un inconnu (nom masculin) : người lạ\n• le ménage (nom masculin) : việc dọn dẹp\n• une facture (nom féminin) : hoá đơn\n• résoudre (verbe) : giải quyết","explications":"• Bài B1 trọn vẹn: khoảng 1/3 kể sự việc, 2/3 nêu ý kiến có lý do và ví dụ.\n• Canh giờ 45 phút: 5 phút dàn ý, 30 phút viết, 10 phút đọc lại và đếm từ.","isPremium":true,"price":19000,"kyNang":"B1-PE-6","vong":"chot","thuTu":6}'::jsonb, '2026-11-04T08:00:25.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1kkd1102c', 'b1pe26d1c032', 1, 'open', 'Écrivez votre texte.', '{}'::jsonb, '{"model":"La colocation, une école de la vie\n\nQuand j''ai trouvé mon premier emploi à Hanoï, il y a deux ans, je n''avais pas assez d''argent pour louer un appartement seul. J''ai donc répondu à une annonce et j''ai emménagé avec trois inconnus dans une grande maison du quartier de Cầu Giấy.\n\nLes premières semaines n''ont pas été faciles. Nous n''avions pas les mêmes horaires, et la question du ménage provoquait souvent des disputes. Finalement, nous avons écrit ensemble quelques règles simples, que nous avons affichées dans la cuisine. Depuis, tout se passe beaucoup mieux, et nous dînons ensemble au moins une fois par semaine.\n\nÀ mon avis, la colocation présente de vrais avantages. Elle permet d''abord de faire des économies, puisque le loyer et les factures sont partagés. Elle apprend aussi à respecter les autres et à résoudre les conflits. Cependant, elle ne convient pas à tout le monde : ceux qui ont besoin de calme et de solitude risquent de s''y sentir mal.\n\nPour ma part, je ne regrette pas mon choix, car mes colocataires sont devenus de vrais amis."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare b int; c int;
begin
  select count(*) into b from public.exercises where id like 'b1pe%';
  select count(*) into c from public.questions where exercise_id like 'b1pe%';
  if b <> 26 or c <> 65 then raise exception 'lô 37: % bài, % câu (cần 26, 65)', b, c; end if;
end $$;
